<?php require_once __DIR__.'/../includes/auth.php';secure_session();verify_csrf();$u=require_login();$name=trim($_POST['name']??'');if(!$name)json_response(['success'=>false,'message'=>'A key name is required.'],422);$count=db()->prepare('SELECT COUNT(*) FROM api_keys WHERE user_id=?');$count->execute([$u['id']]);if((int)$count->fetchColumn()>=10)json_response(['success'=>false,'message'=>'Revoke an existing key before creating another.'],422);$key='imgtr_'.bin2hex(random_bytes(24));db()->prepare('INSERT INTO api_keys(user_id,name,key_hash) VALUES(?,?,?)')->execute([$u['id'],substr($name,0,100),hash('sha256',$key)]);json_response(['success'=>true,'key'=>$key]);
